costs = dict(zip(values('W1::Providers', 'D42:D47'), values('W1::Providers', 'C42:C47')))
coverage = {}
for p, a in zip(values('W1::Coverage', 'C804:C813'), values('W1::Coverage', 'D804:D813')):
    coverage.setdefault(p, set()).add(a)
required = set(values('W1::Required', 'C42:C45'))
providers = list(costs.keys())
best = float('inf')
for i in range(1 << len(providers)):
    sel = [providers[j] for j in range(len(providers)) if (i >> j) & 1]
    covered = set()
    for p in sel:
        covered.update(coverage.get(p, set()))
    if required.issubset(covered):
        cost = sum(costs[p] for p in sel)
        if cost < best:
            best = cost
result = best

